from solution import change_base
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference_change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"
    ds = []
    n = x
    while n > 0:
        ds.append(str(n % base))
        n //= base
    return "".join(reversed(ds))


def test_examples_given_8_base3():
    assert change_base(8, 3) == "22"


def test_examples_given_8_base2():
    assert change_base(8, 2) == "1000"


def test_examples_given_7_base2():
    assert change_base(7, 2) == "111"


@given(st.integers(min_value=0, max_value=10**6), st.integers(min_value=2, max_value=9))
def test_roundtrip_int_parse(x, base):
    s = change_base(x, base)
    assert isinstance(s, str)
    assert int(s, base) == x


@given(st.integers(min_value=0, max_value=10**6), st.integers(min_value=2, max_value=9))
def test_equivalence_to_reference_model(x, base):
    assert change_base(x, base) == reference_change_base(x, base)


@given(st.integers(min_value=0, max_value=10**6), st.integers(min_value=2, max_value=9))
def test_digits_in_range_and_numeric(x, base):
    s = change_base(x, base)
    assert len(s) >= 1
    assert all(c.isdigit() for c in s)
    for c in s:
        assert 0 <= int(c) < base


@given(st.integers(min_value=0, max_value=10**6), st.integers(min_value=2, max_value=9))
def test_no_leading_zeros(x, base):
    s = change_base(x, base)
    if x == 0:
        assert s == "0"
    else:
        assert s[0] != "0"


def test_zero_returns_zero_all_bases():
    for base in range(2, 10):
        assert change_base(0, base) == "0"


@given(st.integers(min_value=2, max_value=9))
def test_single_digit_when_x_less_than_base(base):
    for x in range(0, base):
        assert change_base(x, base) == str(x)


@given(st.integers(min_value=0, max_value=2000), st.integers(min_value=2, max_value=9))
def test_recursive_prefix_suffix_structure(x, base):
    s = change_base(x, base)
    if x >= base:
        q, r = divmod(x, base)
        assert s[-1] == str(r)
        assert s[:-1] == change_base(q, base)
    elif x == 0:
        assert s == "0"
    else:
        assert s == str(x)


@given(st.integers(min_value=0, max_value=6), st.integers(min_value=2, max_value=9))
def test_power_of_base_is_one_followed_by_zeros(k, base):
    x = base ** k
    assert change_base(x, base) == "1" + "0" * k


@given(st.integers(min_value=1, max_value=6), st.integers(min_value=2, max_value=9))
def test_power_minus_one_is_all_max_digits(k, base):
    x = base ** k - 1
    assert change_base(x, base) == str(base - 1) * k


@given(
    st.integers(min_value=0, max_value=10**5),
    st.integers(min_value=0, max_value=10**5),
    st.integers(min_value=2, max_value=9),
)
def test_length_monotonic_in_x(a, b, base):
    x1, x2 = (a, b) if a <= b else (b, a)
    assert len(change_base(x1, base)) <= len(change_base(x2, base))


@given(st.integers(min_value=0, max_value=10**6), st.integers(min_value=2, max_value=9))
def test_value_sum_of_places(x, base):
    s = change_base(x, base)
    total = 0
    for c in s:
        total = total * base + int(c)
    assert total == x
